// static
bool UnionTraits<::chromeos::machine_learning::mojom::TextEntityData::DataView, ::chromeos::machine_learning::mojom::TextEntityDataPtr>::Read(
    ::chromeos::machine_learning::mojom::TextEntityData::DataView input,
    ::chromeos::machine_learning::mojom::TextEntityDataPtr* output) {
  using UnionType = ::chromeos::machine_learning::mojom::TextEntityData;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::NUMERIC_VALUE: {
      *output = UnionType::NewNumericValue(input.numeric_value());
      break;
    }
    case Tag::STRING_VALUE: {
      std::string result_string_value;
      if (!input.ReadStringValue(&result_string_value))
        return false;

      *output = UnionType::NewStringValue(
          std::move(result_string_value));
      break;
    }
    default:

      return false;
  }
  return true;
}

