TextClassifierAsyncWaiter::TextClassifierAsyncWaiter(
    TextClassifier* proxy) : proxy_(proxy) {}

TextClassifierAsyncWaiter::~TextClassifierAsyncWaiter() = default;

void TextClassifierAsyncWaiter::Annotate(
    TextAnnotationRequestPtr request, std::vector<TextAnnotationPtr>* out_outputs) {
  base::RunLoop loop;
  proxy_->Annotate(std::move(request),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<TextAnnotationPtr>* out_outputs
,
             std::vector<TextAnnotationPtr> outputs) {*out_outputs = std::move(outputs);
            loop->Quit();
          },
          &loop,
          out_outputs));
  loop.Run();
}
